   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		DataSet
    */
	public DataSet createDataSet( CreateDataSetCommand command )
    throws ProcessingException, IllegalArgumentException {

		DataSet entity = new DataSet();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	DataSetValidator.getInstance().validate( command );    

            entity.setDataSetId( command.getDataSetId() );
            entity.setName( command.getName() );
            entity.setSchemaVersion( command.getSchemaVersion() );
            entity.setRefreshSchedule( command.getRefreshSchedule() );
            entity.setIsSensitive( command.getIsSensitive() );
            entity.setDataFormat( command.getDataFormat() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of DataSet {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create DataSet - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

   /**
    * Update the provided command.
    * @param		command UpdateDataSetCommand
    * @exception    ProcessingException
    * @exception  	IllegalArgumentException
    * @return		DataSet
    */
    public DataSet updateDataSet( UpdateDataSetCommand command ) 
    throws ProcessingException, IllegalArgumentException {

	    DataSet entity = new DataSet();

    	try {       

			// --------------------------------------
        	// validate 
        	// --------------------------------------    	
        	DataSetValidator.getInstance().validate( command );    

            entity.setDataSetId( command.getDataSetId() );
            entity.setName( command.getName() );
            entity.setSchemaVersion( command.getSchemaVersion() );
            entity.setRefreshSchedule( command.getRefreshSchedule() );
            entity.setIsSensitive( command.getIsSensitive() );
            entity.setWorkspace( command.getWorkspace() );
            entity.setSources( command.getSources() );
            entity.setPipelines( command.getPipelines() );
            entity.setSemanticModels( command.getSemanticModels() );
            entity.setDimensions( command.getDimensions() );
            entity.setMeasures( command.getMeasures() );
            entity.setMetrics( command.getMetrics() );
            entity.setQualityRules( command.getQualityRules() );
            entity.setLineageNode( command.getLineageNode() );
            entity.setTags( command.getTags() );
            entity.setDataFormat( command.getDataFormat() );
        	
        	// ------------------------------------------
        	// persist an existing one
        	// ------------------------------------------ 
        	entity = projector.update(entity);
    	    
			LOGGER.log( Level.INFO, "done saving of DataSet {0} ", entity.toString() );
    	}
        catch (Exception exc) {
            final String errMsg = "Unable to save DataSet - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
    	
    	return entity;
    }
   
