    /**
     * Method to retrieve the DataSet via DataSetFetchOneSummary
     * @param 	summary DataSetFetchOneSummary 
     * @return 	DataSetFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public DataSet getDataSet( DataSetFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DataSetFetchOneSummary arg cannot be null" );
    	
    	DataSet entity = null;
    	UUID id = summary.getDataSetId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	DataSetValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a DataSet using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate DataSet with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


